  --page: #f8fafc;
  --surface: #ffffff;
  --text: #0f172a;
  --muted: #475569;
  --accent: #0284c7;
  --accent-strong: #075985;
  --space: 1.25rem;
  --radius: 1rem;
}

body {
  background: var(--page);
  color: var(--text);
  line-height: 1.6;
}

main,
.site-header,
footer {
  width: min(70rem, calc(100% - 2rem));
