  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.brand,
nav {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand {
  font-weight: 800;
  text-decoration: none;
}

nav {
  flex-wrap: wrap;
}

nav a {
  text-decoration: none;
  font-weight: 650;
}

.event-grid,
.schedule-grid,
.speaker-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: var(--space);
}

.event-card,
.schedule-card,
.speaker-card,
.hero-note,
.registration-form {
  background: var(--surface);
  border-radius: var(--radius);
  padding: var(--space);
